    "path": ".github/workflows/deploy.yml",
    "content": "name: Deploy MissFrozen Gaming (app8888370613)\n\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: tgcloud-deploy-app8888370613\n  cancel-in-progress: false\n\njobs:\n  deploy:\n    runs-on: ubuntu-24.04\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - name: Verify Mini App deployment files are tracked\n        run: |\n          test -f tgcloud.jsonc || { echo \"::error::tgcloud.jsonc is missing from checkout\"; exit 1; }\n          git ls-files --error-unmatch tgcloud.jsonc >/dev/null || { echo \"::error::tgcloud.jsonc is not tracked by Git\"; exit 1; }\n          test -f web/index.html || { echo \"::error::web/index.html is missing\"; exit 1; }\n          test -f web/js/app.js || { echo \"::error::web/js/app.js is missing\"; exit 1; }\n          test -f web/js/contract.js || { echo \"::error::web/js/contract.js is missing\"; exit 1; }\n          echo \"TGCloud config and core Mini App files are present in the checkout.\"\n      - name: Validate syntax, imports and run test suite\n        run: npm run validate\n\n      # Guard: this workflow may ONLY deploy app8888370613. If the token embeds an\n      # app-id (app<digits> prefix/segment) it must match; a token for the\n      # other bot fails the job before anything is pushed.\n      - name: Verify token targets app8888370613\n        if: github.event_name != 'pull_request'\n        env:\n          TGCLOUD_TOKEN: ${{ secrets.TGCLOUD_TOKEN_MISSFROZEN }}\n          EXPECTED_APP: app8888370613\n        run: |\n          if [ -z \"$TGCLOUD_TOKEN\" ]; then echo \"::error::Secret TGCLOUD_TOKEN_MISSFROZEN is not set\"; exit 1; fi\n          FOUND=$(printf '%s' \"$TGCLOUD_TOKEN\" | grep -oE 'app[0-9]{6,}' | head -n1 || true)\n          if [ -n \"$FOUND\" ] && [ \"$FOUND\" != \"$EXPECTED_APP\" ]; then\n            echo \"::error::Token targets $FOUND, expected $EXPECTED_APP. Refusing to deploy.\"\n            exit 1\n          fi\n          if [ -z \"$FOUND\" ]; then\n            echo \"::warning::Token carries no embedded app-id; relying on secret scoping. Confirm TGCLOUD_TOKEN_MISSFROZEN was issued for $EXPECTED_APP in the TGCloud dashboard.\"\n          else\n            echo \"Token app-id verified: $FOUND\"\n          fi\n          grep -q \"$EXPECTED_APP\" tgcloud/lib/config.js || { echo \"::error::config.js does not target $EXPECTED_APP\"; exit 1; }\n\n      - name: Sync cloud revision metadata\n        if: github.event_name != 'pull_request'\n        run: npx tgcloud fetch\n        env:\n          TGCLOUD_TOKEN: ${{ secrets.TGCLOUD_TOKEN_MISSFROZEN }}\n\n      - name: Deploy to TGCloud (app8888370613 only)\n        if: github.event_name != 'pull_request'\n        run: npx tgcloud push\n        env:\n          TGCLOUD_TOKEN: ${{ secrets.TGCLOUD_TOKEN_MISSFROZEN }}\n"
