    "path": "package.json",
    "content": "{\n  \"name\": \"missfrozen-gaming-bot\",\n  \"private\": true,\n  \"devDependencies\": {\n    \"@tgcloud/cli\": \"^0.2.0\"\n  },\n  \"scripts\": {\n    \"postinstall\": \"node scripts/patch-tgcloud-cli.js\",\n    \"deploy\": \"tgcloud push\",\n    \"status\": \"tgcloud status\",\n    \"run\": \"tgcloud run\",\n    \"test\": \"node --test test/**/*.test.js\",\n    \"validate\": \"node scripts/validate.js && npm test\",\n    \"generate:snapshot\": \"node scripts/generate_snapshot.js\",\n    \"generate:pet-migration\": \"node scripts/generate_pet_migration_data.js\"\n  },\n  \"type\": \"module\"\n}\n"
